3	// This file is the end-to-end regression guard for excludeInstanceIds
4	// selections that run after the service's instance list has been REPLACED
5	// within one register batch. It drives JSON batches through runRegister (the
6	// same path as the CLI; every invocation starts from an empty registry, so
7	// registration, health reports, selections and the replacement are all
8	// expressed as items of the one batch) and locks the observable behaviour:
9	//
10	//   - with a, b, c, d healthy and the rotation resting on b, replacing the
11	//     list at the current revision (removing b, keeping the other ids and
12	//     addresses) leaves the position on the removed b: a select excluding c
13	//     chooses d, the next plain select wraps to a, and the one after chooses
14	//     the previously excluded c — the exclusion neither resets the position
15	//     nor becomes a durable restriction on c;
16	//   - every successful select reports the post-replacement revision and the
17	//     address and accepted health sequence of the instance actually chosen;
18	//   - a select carrying the pre-replacement revision is a conflict naming
19	//     both revisions, and excluding every healthy instance is no_healthy
20	//     naming the exclusion; both failures report the current revision and
21	//     carry no target fields, keep their own result slots, and move no
22	//     cursor, so the next valid select continues just after the removed b;
23	//   - a batch containing such failures exits 1 while an all-success batch
24	//     exits 0; per-item results and the final service list keep the existing
25	//     output format.
26	
27	import (
28		"encoding/json"
29		"strings"
30		"testing"
31	)
32	
33	// TestSelectExcludeAfterReplacementKeepsRotation is the all-success half: the
34	// whole rotation sequence after the replacement is observable through the
35	// per-item results, and the final service list proves the exclusion left no
36	// durable trace. The instance lists are submitted out of id order on purpose:
37	// the rotation runs by ascending id, never by submission order.
38	func TestSelectExcludeAfterReplacementKeepsRotation(t *testing.T) {
39		input := `{"requests":[
40			{"type":"register","service":"svc","expectedRevision":0,"instances":[
41				{"id":"d","address":"h4:4"},
42				{"id":"b","address":"h2:2"},
43				{"id":"a","address":"h1:1"},
44				{"id":"c","address":"h3:3"}
45			]},
46			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
47			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
48			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
49			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":true},
50			{"type":"select","service":"svc","expectedRevision":1},
51			{"type":"select","service":"svc","expectedRevision":1},
52			{"type":"register","service":"svc","expectedRevision":1,"instances":[
53				{"id":"d","address":"h4:4"},
54				{"id":"a","address":"h1:1"},
55				{"id":"c","address":"h3:3"}
56			]},
57			{"type":"select","service":"svc","expectedRevision":2,"excludeInstanceIds":["c"]},
58			{"type":"select","service":"svc","expectedRevision":2},
59			{"type":"select","service":"svc","expectedRevision":2}
60		]}`
61		out, code := runRegisterWith(t, input)
62		if code != 0 {
63			t.Fatalf("every request succeeds, exit code must be 0, got %d, output: %s", code, out)
64		}
65		var got registerOutput
66		if err := json.Unmarshal([]byte(out), &got); err != nil {
67			t.Fatalf("output is not JSON: %v\n%s", err, out)
68		}
69		if len(got.Results) != 11 {
70			t.Fatalf("results: %+v", got.Results)
71		}
72	
73		// 0: create at revision 1; 1-4: the observations are accepted without
74		// bumping the registration revision.
75		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
76			t.Fatalf("result 0 create: %+v", r)
77		}
78		for i, seq := range []int64{11, 12, 13, 14} {
79			if r := got.Results[1+i]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != seq {
80				t.Fatalf("result %d health: %+v", 1+i, r)
81			}
82		}
83		// 5-6: the plain rotation takes a then b; the cursor rests on b.
84		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
85			t.Fatalf("result 5 first select: %+v", r)
86		}
87		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 1 {
88			t.Fatalf("result 6 second select: %+v", r)
89		}
90		// 7: the replacement removes b and keeps every other id and address; it
91		// succeeds with changed and bumps the revision to 2.
92		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
93			t.Fatalf("result 7 replacement: %+v", r)
94		}
95		// 8: excluding c continues just after the removed b and chooses d with its
96		// own address and accepted sequence at the post-replacement revision — the
97		// position neither restarts at a nor lands on the excluded c.
98		if r := got.Results[8]; !r.OK || r.InstanceID != "d" || r.Address != "h4:4" || r.Sequence != 14 || r.Revision != 2 {
99			t.Fatalf("result 8 exclude c should choose d: %+v", r)
100		}
101		// 9: a plain select wraps past the end to a.
102		if r := got.Results[9]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 2 {
103			t.Fatalf("result 9 should wrap to a: %+v", r)
104		}
105		// 10: the next plain select chooses c — the earlier exclusion was scoped
106		// to its one request and never removed c from the rotation.
107		if r := got.Results[10]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
108			t.Fatalf("result 10 should choose the previously excluded c: %+v", r)
109		}
110	
111		// The final list keeps the existing sorting and field meanings: revision 2,
112		// b gone, and the surviving instances healthy with the sequences accepted
113		// before the replacement — the exclude request made c neither unhealthy
114		// nor unregistered.
115		if len(got.Services) != 1 {
116			t.Fatalf("services: %+v", got.Services)
117		}
118		svc := got.Services[0]
119		if svc.Service != "svc" || svc.Revision != 2 {
120			t.Fatalf("service view: %+v", svc)
121		}
122		wantInsts := []registerInstance{
123			{ID: "a", Address: "h1:1", Health: "healthy", Sequence: 11},
124			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 13},
125			{ID: "d", Address: "h4:4", Health: "healthy", Sequence: 14},
126		}
127		if len(svc.Instances) != len(wantInsts) {
128			t.Fatalf("instances: %+v", svc.Instances)
129		}
130		for i, want := range wantInsts {
131			if svc.Instances[i] != want {
132				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
133			}
134		}
135	}
136	
137	// TestSelectExcludeFailuresAfterReplacementKeepPosition is the failure half:
138	// after the replacement, a stale-revision select conflicts and an
139	// exclude-everything select is no_healthy. Both failures keep their own
140	// result slots, report the current revision, carry no target fields in the
141	// raw JSON, and move no cursor — the valid selects after them continue just
142	// after the removed b. The batch exits 1 because it contains failures.
143	func TestSelectExcludeFailuresAfterReplacementKeepPosition(t *testing.T) {
144		input := `{"requests":[
145			{"type":"register","service":"svc","expectedRevision":0,"instances":[
146				{"id":"a","address":"h1:1"},
147				{"id":"b","address":"h2:2"},
148				{"id":"c","address":"h3:3"},
149				{"id":"d","address":"h4:4"}
150			]},
151			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
152			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
153			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
154			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":true},
155			{"type":"select","service":"svc","expectedRevision":1},
156			{"type":"select","service":"svc","expectedRevision":1},
157			{"type":"register","service":"svc","expectedRevision":1,"instances":[
158				{"id":"a","address":"h1:1"},
159				{"id":"c","address":"h3:3"},
160				{"id":"d","address":"h4:4"}
161			]},
162			{"type":"select","service":"svc","expectedRevision":1},
163			{"type":"select","service":"svc","expectedRevision":2,"excludeInstanceIds":["a","c","d"]},
164			{"type":"select","service":"svc","expectedRevision":2},
165			{"type":"select","service":"svc","expectedRevision":2}
166		]}`
167		out, code := runRegisterWith(t, input)
168		if code != 1 {
169			t.Fatalf("batch contains failures, exit code must be 1, got %d, output: %s", code, out)
170		}
171		var got registerOutput
172		if err := json.Unmarshal([]byte(out), &got); err != nil {
173			t.Fatalf("output is not JSON: %v\n%s", err, out)
174		}
175		// One result per request, in input order: the failed items keep their
176		// slots and the later valid selects are still processed.
177		if len(got.Results) != 12 {
178			t.Fatalf("results: %+v", got.Results)
179		}
180	
181		// 5-6: the plain rotation takes a then b; the cursor rests on b.
182		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Sequence != 11 {
183			t.Fatalf("result 5 first select: %+v", r)
184		}
185		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Sequence != 12 {
186			t.Fatalf("result 6 second select: %+v", r)
187		}
188		// 7: the replacement removes b and bumps the revision to 2.
189		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
190			t.Fatalf("result 7 replacement: %+v", r)
191		}
192		// 8: a caller still using the pre-replacement revision gets a conflict
193		// stating the expected and actual revisions and reporting the current one.
194		if r := got.Results[8]; r.OK || r.Error != "conflict" ||
195			r.Reason != `service "svc" is at revision 2, not 1` ||
196			r.Revision != 2 || !hasRevisionPair(r, 1, 2) {
197			t.Fatalf("result 8 stale-revision select must conflict: %+v", r)
198		}
199		// 9: the correct revision with every healthy instance excluded is
200		// no_healthy; the reason says the exclusion removed them all.
201		if r := got.Results[9]; r.OK || r.Error != "no_healthy" ||
202			!strings.Contains(r.Reason, "excludeInstanceIds") || r.Revision != 2 {
203			t.Fatalf("result 9 exclude-everything must be no_healthy naming the exclusion: %+v", r)
204		}
205		// Both failures fabricate no target: the raw JSON of their results carries
206		// no instanceId, address or sequence field at all.
207		for _, i := range []int{8, 9} {
208			raw := string(mustResultJSON(t, out, i))
209			for _, field := range []string{`"instanceId"`, `"address"`, `"sequence"`} {
210				if strings.Contains(raw, field) {
211					t.Fatalf("result %d must carry no %s field: %s", i, field, raw)
212				}
213			}
214		}
215		// 10: the failures moved no cursor — the rotation continues just after the
216		// removed b and picks c, not d (skipping the due instance) and not a
217		// (restarting from the smallest id).
218		if r := got.Results[10]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
219			t.Fatalf("result 10 should resume after the removed b at c: %+v", r)
220		}
221		// 11: only the following select moves on to d.
222		if r := got.Results[11]; !r.OK || r.InstanceID != "d" || r.Address != "h4:4" || r.Sequence != 14 || r.Revision != 2 {
223			t.Fatalf("result 11 should continue to d: %+v", r)
224		}
225	
226		// The final list reflects only the committed state: revision 2, b removed,
227		// and the surviving instances still healthy with their accepted sequences —
228		// the failed selects changed nothing.
229		if len(got.Services) != 1 {
230			t.Fatalf("services: %+v", got.Services)
231		}
232		svc := got.Services[0]
233		if svc.Service != "svc" || svc.Revision != 2 {
234			t.Fatalf("service view: %+v", svc)
235		}
236		wantInsts := []registerInstance{
237			{ID: "a", Address: "h1:1", Health: "healthy", Sequence: 11},
238			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 13},
239			{ID: "d", Address: "h4:4", Health: "healthy", Sequence: 14},
240		}
241		if len(svc.Instances) != len(wantInsts) {
242			t.Fatalf("instances: %+v", svc.Instances)
243		}
244		for i, want := range wantInsts {
245			if svc.Instances[i] != want {
246				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
247			}
248		}
249	}
