1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"os"
9		"strings"
10		"testing"
11	)
12	
13	// runRegisterWith runs runRegister with the given stdin and captured stdout.
14	func runRegisterWith(t *testing.T, input string) (string, int) {
15		t.Helper()
16		oldStdin := os.Stdin
17		oldStdout := os.Stdout
18		defer func() {
19			os.Stdin = oldStdin
20			os.Stdout = oldStdout
21		}()
22		inR, inW, err := os.Pipe()
23		if err != nil {
24			t.Fatalf("pipe: %v", err)
25		}
26		os.Stdin = inR
27		go func() {
28			defer inW.Close()
29			_, _ = inW.WriteString(input)
30		}()
31		outR, outW, err := os.Pipe()
32		if err != nil {
33			t.Fatalf("pipe: %v", err)
34		}
35		os.Stdout = outW
36		code := runRegister()
37		outW.Close()
38		var buf bytes.Buffer
39		if _, err := buf.ReadFrom(outR); err != nil {
40			t.Fatalf("read stdout: %v", err)
41		}
42		return buf.String(), code
43	}
44	
45	// hasRevisionPair reports whether r carries a registration-revision
46	// conflict's expectedRevision/actualRevision pair, including when either value
47	// is 0 — an explicit 0 must stay present in the JSON rather than looking like
48	// an omitted field.
49	func hasRevisionPair(r registerResult, expected, actual int) bool {
50		return r.ExpectedRevision != nil && *r.ExpectedRevision == expected &&
51			r.ActualRevision != nil && *r.ActualRevision == actual
52	}
53	
54	// omitsRevisionPair reports that r carries neither revision comparison field,
55	// as success, invalid, not_found, stale, no_healthy and a same-sequence
56	// health-content conflict all do.
57	func omitsRevisionPair(r registerResult) bool {
58		return r.ExpectedRevision == nil && r.ActualRevision == nil
59	}
60	
61	func TestRegisterSuccess(t *testing.T) {
62		input := `{"requests":[
63			{"service":"b","expectedRevision":0,"instances":[{"id":"b2","address":"h2:2"},{"id":"b1","address":"h1:1"}]},
64			{"service":"b","expectedRevision":1,"instances":[{"id":"b1","address":"h1:1"},{"id":"b2","address":"h2:2"}]},
65			{"service":"a","expectedRevision":0,"instances":[]}
66		]}`
67		out, code := runRegisterWith(t, input)
68		if code != 0 {
69			t.Fatalf("exit code: %d, output: %s", code, out)
70		}
71		var got registerOutput
72		if err := json.Unmarshal([]byte(out), &got); err != nil {
73			t.Fatalf("output is not JSON: %v\n%s", err, out)
74		}
75		if len(got.Results) != 3 {
76			t.Fatalf("results: %+v", got.Results)
77		}
78		want := []registerResult{
79			{Service: "b", OK: true, Changed: true, Revision: 1},
80			{Service: "b", OK: true, Changed: false, Revision: 1},
81			{Service: "a", OK: true, Changed: true, Revision: 1},
82		}
83		for i := range want {
84			if got.Results[i] != want[i] {
85				t.Fatalf("result %d: got %+v want %+v", i, got.Results[i], want[i])
86			}
87		}
88		// Services sorted by name; instances sorted by id; empty list kept.
89		if len(got.Services) != 2 {
90			t.Fatalf("services: %+v", got.Services)
91		}
92		if got.Services[0].Service != "a" || got.Services[0].Revision != 1 || len(got.Services[0].Instances) != 0 {
93			t.Fatalf("service a: %+v", got.Services[0])
94		}
95		if got.Services[1].Service != "b" || got.Services[1].Revision != 1 {
96			t.Fatalf("service b: %+v", got.Services[1])
97		}
98		insts := got.Services[1].Instances
99		if len(insts) != 2 || insts[0].ID != "b1" || insts[0].Address != "h1:1" || insts[1].ID != "b2" {
100			t.Fatalf("service b instances: %+v", insts)
101		}
102	}
103	
104	func TestRegisterFailuresDoNotAbort(t *testing.T) {
105		input := `{"requests":[
106			{"service":"a","expectedRevision":0,"instances":[{"id":"x","address":"h:1"}]},
107			{"service":"a","expectedRevision":5,"instances":[{"id":"y","address":"h:2"}]},
108			{"service":"a","expectedRevision":1,"instances":[{"id":"y","address":"h:2"}]},
109			{"service":"a","expectedRevision":2,"instances":[{"id":"","address":"h:1"}]},
110			{"service":"a","expectedRevision":2,"instances":[{"id":"z","address":"nope"}]},
111			{"service":"b","expectedRevision":1,"instances":[]}
112		]}`
113		out, code := runRegisterWith(t, input)
114		if code != 1 {
115			t.Fatalf("exit code: %d", code)
116		}
117		var got registerOutput
118		if err := json.Unmarshal([]byte(out), &got); err != nil {
119			t.Fatalf("output is not JSON: %v\n%s", err, out)
120		}
121		if len(got.Results) != 6 {
122			t.Fatalf("results: %+v", got.Results)
123		}
124		// 0: create
125		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
126			t.Fatalf("result 0: %+v", r)
127		}
128		// 1: conflict, expected 5 actual 1
129		if r := got.Results[1]; r.OK || r.Error != "conflict" || !hasRevisionPair(r, 5, 1) || r.Revision != 1 {
130			t.Fatalf("result 1: %+v", r)
131		}
132		// 2: update to rev 2
133		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
134			t.Fatalf("result 2: %+v", r)
135		}
136		// 3: invalid content with a matching revision: still invalid, list untouched
137		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
138			t.Fatalf("result 3: %+v", r)
139		}
140		// 4: invalid address
141		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
